Theorem lock_spec : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (P v lo : Z),
  a0 = wz P -> P mod 4 = 0 -> 0 <= v < 2^31 -> 0 <= P -> P + 4 <= lo ->
  rw_cells bsegs m P [C4 (wz v)] ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 48 <= bv_unsigned sp ->
  mem_inv bsegs m ->
  evt bsegs (lock_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P v lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 DEPOT_LOCK) fc None m (seg_rom bsegs)).
